def expand_minimum(existing):
    from collections import Counter
    counts=Counter((q['category'],q['difficulty']) for q in existing)
    used={q['prompt'] for q in existing}
    result=[]
    for category,(template,pool) in POOLS.items():
        candidates=iter(pool.split(';'))
        number=0
        for difficulty in ('easy','medium','hard'):
            for _ in range(max(0,10-counts[category,difficulty])):
                label,answer=next(candidates).split('|')
                prompt=template.format(x=label)
                number+=1
                assert prompt not in used
                used.add(prompt)
                variants=[answer]
                if category=='language' and answer=='Норвежки': variants.extend(['Исландски','Фарьорски'])
                if ' ' in answer and category in ('art','cinema','music','literature'):
                    variants.append(answer.split()[-1])
                result.append(dict(id=f'pack5-{category}-{number:02d}',category=category,difficulty=difficulty,prompt=prompt,answer=answer,alternatives=variants,explanation=f'{label.capitalize()} — {answer}.',source_url='https://bg.wikipedia.org/wiki/'+quote(answer.replace(' ','_')),pack_version=5))
    return result
